// src/engine/skillGuide.js
var REPORT_SKILL = {
  bazi: "bazi",
  mangpai: "bazi",
  liuyao: "liuyao",
  huangli: "huangli",
  ziwei: "ziwei",
  qimen: "qimen",
  tarot: "tarot",
  name: "name",
  fengshui: "fengshui"
};
function skillOfReport(type) {
  const key = REPORT_SKILL[type];
  if (!key) return null;
  return BUILTIN_SKILLS.find((s) => s.key === key) || null;
}
function friendlyMethod(skill) {
  if (!skill) return "";
  let t = skill.sys || "";
  t = t.replace(/^你(?:精通|通晓|擅长)\S{0,12}[，,]\s*/, "").replace(/^你(?:精通|通晓|擅长)\S{0,12}。/s, "");
  const cleaned = t.trim();
  return cleaned || skill.desc || "";
}
function guidePointsOf(type) {
  const skill = skillOfReport(type);
  if (!skill) return null;
  return {
    icon: skill.icon,
    name: skill.name,
    desc: skill.desc,
    method: skill.sys,
    methodText: friendlyMethod(skill)
  };
}
function guideSectionOf(type) {
  const g = guidePointsOf(type);
  if (!g) return null;
  return {
    key: "guide",
    kind: "guide",
    title: "\u6280\u6CD5\u603B\u7EB2",
    data: g
  };
}

