function buildChart(year, month, day, hour, gender) {
  const hourVal = hour ?? 12;
  const pad2 = (n) => String(n).padStart(2, "0");
  let ct = null;
  try {
    ct = buildBaziFromSolar({
      solarTime: `${year}-${pad2(month)}-${pad2(day)} ${pad2(hourVal)}:00`,
      gender: gender === "\u5973" ? 0 : 1,
      // 参天约定：0 女 / 1 男
      sect: 2
      // 晚子时（23:00-23:59）日柱仍算当天
    });
  } catch (e) {
    ct = null;
  }
  const date = new Date(year, month - 1, day);
  let yp, mp, dp;
  if (ct) {
    yp = { gan: ct.\u5E74\u67F1.\u5929\u5E72.\u5929\u5E72, zhi: ct.\u5E74\u67F1.\u5730\u652F.\u5730\u652F, year };
    mp = { gan: ct.\u6708\u67F1.\u5929\u5E72.\u5929\u5E72, zhi: ct.\u6708\u67F1.\u5730\u652F.\u5730\u652F };
    dp = { gan: ct.\u65E5\u67F1.\u5929\u5E72.\u5929\u5E72, zhi: ct.\u65E5\u67F1.\u5730\u652F.\u5730\u652F };
  } else {
    yp = yearPillar(date);
    mp = monthPillar(date, TIAN_GAN.indexOf(yp.gan));
    dp = dayPillar(date);
  }
  const hp = hourPillar(hourVal, TIAN_GAN.indexOf(dp.gan));
  const pillars = [
    { label: "\u5E74\u67F1", ...yp, shiShen: shiShen(dp.gan, yp.gan) },
    { label: "\u6708\u67F1", ...mp, shiShen: shiShen(dp.gan, mp.gan) },
    { label: "\u65E5\u67F1", ...dp, shiShen: "\u65E5\u4E3B" },
    { label: "\u65F6\u67F1", ...hp, shiShen: shiShen(dp.gan, hp.gan) }
  ];
  const count = wuxingCount(pillars);
  const strength = judgeStrength(GAN_WUXING[TIAN_GAN.indexOf(dp.gan)], count);
  const fav = favorableElements(GAN_WUXING[TIAN_GAN.indexOf(dp.gan)], strength);
  const shengxiao = SHENGXIAO[DI_ZHI.indexOf(yp.zhi)];
  const wuxingRank = Object.entries(count).sort((a, b) => b[1] - a[1]).map(([k]) => k);
  const result = {
    year,
    month,
    day,
    hour: hourVal,
    gender,
    pillars,
    dayMaster: dp.gan,
    dayMasterWx: GAN_WUXING[TIAN_GAN.indexOf(dp.gan)],
    shengxiao,
    wuxing: count,
    wuxingRank,
    strength,
    favorable: fav.favorable,
    avoid: fav.avoid,
    sheng: WUXING_SHENG,
    ke: WUXING_KE
  };
  if (ct && ct.\u5927\u8FD0) {
    result.qiYunAge = ct.\u5927\u8FD0.\u8D77\u8FD0\u5E74\u9F84;
    result.qiYunDate = ct.\u5927\u8FD0.\u8D77\u8FD0\u65E5\u671F;
    result.qiYunText = (() => {
      try {
        const [yy, mm, dd] = String(result.qiYunDate).split("-").map(Number);
        const days = Math.round((new Date(yy, mm - 1, dd) - new Date(year, month - 1, day)) / 864e5);
        const y = Math.floor(days / 365.25);
        const m = Math.round((days - y * 365.25) / 30.44);
        return m > 0 ? `${y}\u5C81${m}\u4E2A\u6708` : `${y}\u5C81`;
      } catch (e) {
        return "";
      }
    })();
    const dayGan = dp.gan;
    const firstList = [];
    const qyYear = Number(String(result.qiYunDate || "").split("-")[0]);
    if (qyYear && qyYear > year && mp.gan && mp.zhi) {
      const fGz = `${mp.gan}${mp.zhi}`;
      const fZhiGan = (ZHI_CANGGAN[DI_ZHI.indexOf(mp.zhi)] || []).slice(0, 1)[0] || "";
      firstList.push({
        key: fGz,
        g: mp.gan,
        z: mp.zhi,
        start: year,
        end: qyYear - 1,
        startAge: 1,
        endAge: Math.max(1, result.qiYunAge - 1),
        ganShiShen: shiShen(dayGan, mp.gan),
        zhiShiShen: fZhiGan ? [shiShen(dayGan, fZhiGan)] : [],
        zhiCanGan: ZHI_CANGGAN[DI_ZHI.indexOf(mp.zhi)] || [],
        isFirst: true
      });
    }
    result.daYunList = [
      ...firstList,
      ...(ct.\u5927\u8FD0.\u5927\u8FD0 || []).map((d) => {
        const gz = d.\u5E72\u652F || "";
        return {
          key: gz,
          g: gz.charAt(0),
          z: gz.charAt(1) || "",
          start: d.\u5F00\u59CB\u5E74\u4EFD,
          end: d.\u7ED3\u675F,
          startAge: d.\u5F00\u59CB\u5E74\u9F84,
          endAge: d.\u7ED3\u675F\u5E74\u9F84,
          ganShiShen: d.\u5929\u5E72\u5341\u795E,
          zhiShiShen: d.\u5730\u652F\u5341\u795E,
          zhiCanGan: d.\u5730\u652F\u85CF\u5E72
        };
      })
    ];
  }
  return result;
}

