          "\u5546\u4E1A": "\u8D44\u8D22\u5145\u8DB3\uFF0C\u5F80\u590D\u83B7\u5229\u3002",
          "\u5BB6\u5B85": "\u7956\u57FA\u6DF1\u539A\uFF0C\u65E7\u4E1A\u590D\u5149\uFF0C\u5409\u3002",
          "\u6218\u5F81": "\u519B\u529B\u539A\u5B9E\uFF0C\u53EF\u4EE5\u653B\u590D\u57CE\u6C60\u4E5F\u3002",
          "\u75BE\u75C5": "\u75C5\u8005\u7CBE\u795E\u5145\u8DB3\uFF0C\u6C14\u4F53\u4E30\u8174\uFF0C\u65E0\u60A3\u4E5F\u3002",
          "\u516D\u7532": "\u751F\u7537\u3002",
          "\u5931\u7269": "\u5B9C\u81EA\u5FD6\u5EA6\u3002"
