var GAODAO_YIDUAN = {};
for (const hex of raw.hexagrams) {
  const guaName = GAODAO_ORDER[hex.number - 1];
  if (!guaName) continue;
  GAODAO_YIDUAN[guaName] = {
    guaName,
    intro: hex.intro,
    lines: hex.lines.filter((line) => line.type === "line").map((line) => ({
      line: line.line,
      title: line.title,
      // 原始数据中少数爻（约2%）未单独摘出象辞，字段为 null，这里统一归一化为空串
      xiang: line.xiang ?? "",
      commentary: line.commentary
    }))
  };
}
function getGaoDaoYiDuan(yaoString) {
  const guaName = getGuaName(yaoString);
  const entry = GAODAO_YIDUAN[guaName];
  if (!entry) {
    return void 0;
  }
  const movingPositions = getMovingYaoPositions(yaoString);
  const movingLines = entry.lines.filter((line) => movingPositions.includes(line.line));
  return {
    guaName,
    intro: entry.intro,
    movingLines
  };
}

