function makeMinor(suitKey, data) {
  return data.map((d) => ({
    id: `${suitKey[0]}${d.n}`,
    suit: suitKey,
    num: d.n,
    rank: RANK_NAME[d.n],
    rankEn: RANK_NAME_EN[d.n],
    name: `${SUIT_META[suitKey].name}${RANK_NAME[d.n]}`,
    en: `${RANK_NAME_EN[d.n]} of ${SUIT_META[suitKey].en}`,
    up: d.up,
    rev: d.rev,
    kw: d.kw
  }));
}
