function detectTheme(question) {
  if (!question) return null;
  let best = null;
  let bestScore = 0;
  for (const [key, words] of Object.entries(THEME_KEYWORDS)) {
    let s = 0;
    for (const w of words) if (question.includes(w)) s++;
    if (s > bestScore) {
      bestScore = s;
      best = key;
    }
  }
  return bestScore > 0 ? best : null;
}
